import{_ as a,o as n,a as p,b as c}from"./app.DII24pJb.js";const l="/ascendc.github.io/pr/6322/assets/inplace_add_atomic_dataflow_plain.DeJs7AMU.png",t="/ascendc.github.io/pr/6322/assets/inplace_add_atomic_dataflow_atomic.3lKFP82F.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"指令优化","link":"/guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization"},{"text":"原地加法指令优化","link":"/guide/operator_practice/simt_operator_optimization/instruction_optimization/inplace_add_instruction_optimization"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/instruction_optimization/inplace_add_instruction_optimization.md","filePath":"guide/operator_practice/simt_operator_optimization/instruction_optimization/inplace_add_instruction_optimization.md","lastUpdated":1789962215000}'),e={name:"guide/operator_practice/simt_operator_optimization/instruction_optimization/inplace_add_instruction_optimization.md"};function i(o,s,d,r,_,w){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>原地加法指令优化</h1><p>【优先级】中</p><p>【描述】如<code>a[index] += b[index]</code>、<code>a[index] += b[index] * c[index]</code>，原地加法是算子中常见的数据更新形式。在上述使用加法运算符的程序中，累加目标<code>a[index]</code>的旧值必须先从L2 Cache读入寄存器才能参与计算，完成加法运算后，结果值从寄存器写回L2 Cache，每个元素都经历一次旧值读入、新值写出的寄存器往返。改用<code>asc_atomic_add(&amp;a[index], b[index])</code>这类<a href="../../../../api/SIMT-API/atomic_operations/atomic_operations_intro.html">原子加接口</a>后，“读出旧值—计算新值—写回新值”三步作为一个不可分割的整体在L2 Cache侧完成，旧值不再进入寄存器，省去其进出寄存器的数据往返。</p><p>【样例介绍】本节以<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/03_simt_api/03_best_practices/03_instruction_optimizations/inplace_add_atomic/README.md">inplace_add_atomic样例</a>为载体说明上述优化方向，样例对三个形状均为[4194304]的int32_t数组执行逐元素累加，包含两组对照，一组为三操作数乘加<code>a[index] += b[index] * c[index]</code>，另一组为两操作数加法<code>a[index] += b[index]</code>。样例启动64个线程块、每个线程块2048个线程，线程块数量为运行时查询到的AIV核数，各组对照仅改变累加语句的代码，即普通原地加或<code>asc_atomic_add</code>，其余保持一致。</p><div data-filter="950"><p>下文性能数据均使用msOpProf工具在Ascend 950PR系列产品上采集，指标为Task Duration，即Task整体耗时、算子端到端耗时。</p></div><p><strong>优化原理</strong></p><p>两组对照的原理相同：普通原地加中，累加目标的旧值需经L2 Cache读入寄存器，加法完成后新值再从寄存器写回L2 Cache；改用原子加后，旧值的读出、加法与写回均在L2 Cache侧作为一个不可分割的整体完成，旧值不再经“L2 Cache→寄存器→L2 Cache”的往返。两种累加方式的数据流转分别如下图所示。</p><p><strong>图 1</strong> 普通原地加的数据流转</p><p><img src="'+l+'" alt></p><p><strong>图 2</strong> 原子加的数据流转</p><p><img src="'+t+`" alt></p><p>以三操作数乘加为例：普通原地加中<code>a[index]</code>、<code>b[index]</code>、<code>c[index]</code>三者都经L2 Cache读入寄存器，乘加完成后<code>a[index]</code>的新值再从寄存器写回L2 Cache，每个元素产生3次读、1次写；原子加中只有<code>b[index]</code>与<code>c[index]</code>读入寄存器并算出乘积，乘积作为原子加的操作数下发，<code>a[index]</code>不进入寄存器，每个元素的读从3次降为2次。<code>b</code>、<code>c</code>的读取与乘法计算完全相同，性能差异仅来自省去的<code>a[index]</code>旧值数据往返。</p><p><strong>三操作数乘加</strong></p><p>【反例】累加目标的旧值读入寄存器，在核内完成读改写。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_muladd_plain</span><span class="p">(</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">element_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">element_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">a</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">b</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">c</span><span class="p">[</span><span class="n">index</span><span class="p">];</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现中，各线程按grid-stride方式遍历数组，即每个线程以总线程数为固定步长，分次处理数组中不同位置的元素。每个元素的乘加都需将<code>a[index]</code>旧值读入寄存器、加法完成后写回。该实现的性能数据如下：</p><table><thead><tr><th align="center">累加方式</th><th align="center">Task Duration（μs）</th><th align="center">耗时相对基线</th></tr></thead><tbody><tr><td align="center">a[index] += b[index] * c[index]</td><td align="center">51.62</td><td align="center">1×</td></tr></tbody></table><p>【正例】改用原子加，将累加下发到L2 Cache侧完成。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_muladd_atomic</span><span class="p">(</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">element_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">element_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="o">&amp;</span><span class="n">a</span><span class="p">[</span><span class="n">index</span><span class="p">],</span><span class="w"> </span><span class="n">b</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">c</span><span class="p">[</span><span class="n">index</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现的功能与反例一致，线程块数量、线程数、输入读取方式均相同，唯一变化是累加语句的代码。本样例中各线程更新的目标地址互不重叠，不存在同地址竞争，算子结果的正确性并不依赖原子性；此处使用原子加是为了省去旧值进出寄存器的数据往返，获取性能收益。该实现的性能数据如下：</p><table><thead><tr><th align="center">累加方式</th><th align="center">Task Duration（μs）</th><th align="center">耗时相对基线</th></tr></thead><tbody><tr><td align="center">asc_atomic_add</td><td align="center">47.51</td><td align="center"><strong>0.92×</strong></td></tr></tbody></table><p>根据Task Duration数据，改用原子加后执行耗时从51.62μs下降至47.51μs，降幅约8.0%。</p><p><strong>两操作数加法</strong></p><p>【反例】累加目标的旧值读入寄存器，在核内完成读改写。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_add_plain</span><span class="p">(</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">element_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">element_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">a</span><span class="p">[</span><span class="n">index</span><span class="p">]</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">b</span><span class="p">[</span><span class="n">index</span><span class="p">];</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>该实现的性能数据如下：</p><table><thead><tr><th align="center">累加方式</th><th align="center">Task Duration（μs）</th><th align="center">耗时相对基线</th></tr></thead><tbody><tr><td align="center">a[index] += b[index]</td><td align="center">39.18</td><td align="center">1×</td></tr></tbody></table><p>【正例】改用原子加，将累加下发到L2 Cache侧完成。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_add_atomic</span><span class="p">(</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">element_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">element_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="o">&amp;</span><span class="n">a</span><span class="p">[</span><span class="n">index</span><span class="p">],</span><span class="w"> </span><span class="n">b</span><span class="p">[</span><span class="n">index</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>该实现的核函数遍历方式、线程规模与反例完全一致，仅将累加语句改写为原子加。两操作数加法中每个元素的读从2次降为1次，数据往返的节省比例与三操作数乘加相当。该实现的性能数据如下：</p><table><thead><tr><th align="center">累加方式</th><th align="center">Task Duration（μs）</th><th align="center">耗时相对基线</th></tr></thead><tbody><tr><td align="center">asc_atomic_add</td><td align="center">36.52</td><td align="center"><strong>0.93×</strong></td></tr></tbody></table><p>根据Task Duration数据，改用原子加后执行耗时从39.18μs下降至36.52μs，降幅约6.8%。</p><p>两组对照的性能数据汇总如下：</p><table><thead><tr><th align="center">计算形式</th><th align="center">累加方式</th><th align="center">Task Duration（μs）</th><th align="center">耗时相对基线</th></tr></thead><tbody><tr><td align="center"><strong>三操作数乘加</strong></td><td align="center"><strong>asc_atomic_add</strong></td><td align="center"><strong>47.51</strong></td><td align="center"><strong>0.92×</strong></td></tr><tr><td align="center">三操作数乘加</td><td align="center">a[index] += b[index] * c[index]</td><td align="center">51.62</td><td align="center">1×</td></tr><tr><td align="center"><strong>两操作数加法</strong></td><td align="center"><strong>asc_atomic_add</strong></td><td align="center"><strong>36.52</strong></td><td align="center"><strong>0.93×</strong></td></tr><tr><td align="center">两操作数加法</td><td align="center">a[index] += b[index]</td><td align="center">39.18</td><td align="center">1×</td></tr></tbody></table><p><strong>适用边界</strong></p><p>该优化仅适用于逐元素原地更新，使用前需确认各线程原子操作的目标地址互不重叠：</p><ul><li><strong>适用的逐元素原地更新</strong>：每个线程只更新自己负责的元素，目标地址在线程间天然不重叠，如本样例的grid-stride遍历。</li><li><strong>不适用的归约累加</strong>：多个线程向同一地址累加，如直方图统计，此时同一地址上的原子操作只能排队串行执行，直接使用原子加会因地址竞争显著劣化性能，应采用<a href="./atomic_instruction_optimization.html">分层归约</a>——先在各线程块的UB中局部累加，再向GM汇总。</li></ul><p>此外，原子加支持的数据类型必须是支持指令优化的数据类型；对int64_t等类型，该执行路径的收益需实测确认，不使用返回值时能否生成更优原子指令与数据类型相关，参见<a href="../../../../api/SIMT-API/atomic_operations/asc_atomic_add.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">asc_atomic_add约束说明</a>。</p><p>【总结】原地累加场景中，若累加目标的旧值仅用于累加、不参与其他计算，且各线程目标地址互不重叠，可优先考虑用原子加完成累加：旧值的读出、加法与写回均在L2 Cache侧作为一个不可分割的整体完成，省去旧值进出寄存器的数据往返，实测收益约7%~8%。</p></article></div>`,1)])])}const m=a(e,[["render",i]]);export{g as __pageData,m as default};
